// Generated by scripts/build-embed.mjs: the design system's CSS, scoped to :host.
import { EMBED_CSS, FONT_FACES } from "embed-css";

/** @font-face doesn't apply inside a shadow root, so the fonts are registered on the page, once. */
export function ensureFonts(base: string) {
  if (document.getElementById("whyte-embed-fonts")) return;
  const style = document.createElement("style");
  style.id = "whyte-embed-fonts";
  style.textContent = FONT_FACES.replaceAll("__FONT_BASE__", `${base}/embed/fonts`);
  document.head.appendChild(style);
}

/**
 * Gives a host element a shadow root with the design system's styles, a
 * mount point, and a light-DOM slot for Turnstile (which renders in the page).
 */
export function prepareShadow(host: HTMLElement, base: string, bodyClass = "ds-body"): { mount: HTMLElement; turnstile: HTMLElement } {
  ensureFonts(base);
  const shadow = host.shadowRoot ?? host.attachShadow({ mode: "open" });
  const style = document.createElement("style");
  style.textContent = EMBED_CSS;
  const mount = document.createElement("div");
  mount.className = bodyClass;
  shadow.replaceChildren(style, mount);
  const turnstile = document.createElement("div");
  turnstile.slot = "turnstile";
  host.appendChild(turnstile);
  return { mount, turnstile };
}
